<?php if(!defined('ABSPATH'))exit;$d=woogit_portal_data();get_header();if(!$d['authenticated']){woogit_render_status('error','نشست شما منقضی شده است.');get_footer();return;}$p=$d['payments'];$orders=(array)($p['orders']??[]);?><section class="wg-section wg-portal"><div class="wg-container"><div class="wg-section__head"><div><span class="wg-eyebrow">Payments</span><h1>تاریخچه پرداخت‌ها</h1><p>سوابق خرید WooGit از WooCommerce رسمی سایت نمایش داده می‌شود.</p></div></div><?php if(!$orders): ?><div class="wg-card wg-empty"><h2>هنوز پرداختی ثبت نشده است.</h2><p>پس از اولین Order معتبر، سوابق اینجا نمایش داده می‌شود.</p><a class="wg-btn" href="<?php echo esc_url(woogit_page_url('pricing')); ?>">مشاهده پلن‌ها</a></div><?php else: ?><div class="wg-table-wrap"><table class="wg-table"><thead><tr><th>Order</th><th>تاریخ</th><th>وضعیت</th><th>روش پرداخت</th><th>مبلغ</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td>#<?php echo esc_html((int)($o['order_id']??0)); ?></td><td><?php echo woogit_safe_text($o['created_at']??'—'); ?></td><td><span class="wg-status"><?php echo woogit_safe_text($o['status']??'—'); ?></span></td><td><?php echo woogit_safe_text($o['payment_method_title']??$o['payment_method']??'—'); ?></td><td><?php echo woogit_safe_text($o['total']??'—'); ?> <?php echo woogit_safe_text($o['currency']??''); ?></td></tr><?php endforeach; ?></tbody></table></div><?php if((int)($p['total_pages']??1)>1): ?><nav class="wg-pagination" aria-label="صفحات پرداخت"><span>صفحه <?php echo esc_html((int)($p['page']??1)); ?> از <?php echo esc_html((int)$p['total_pages']); ?></span></nav><?php endif;endif; ?></div></section><?php get_footer(); ?>